	padding: 0px;
	margin: 0px;
	font-size: 14px;
	color: #555;
}

.ui-inputtext {
	border: 1px solid #ced4da;
	padding: 0px 6px;
}

.ui-autocomplete-panel {
	background: rgba(255, 255, 255, 0.7);
	padding: 10px;
	margin-top: 15px;
	max-height: 223px;
	width: 400px;
}

.ui-autocomplete-item {
	padding: 0px;
	color: #555;
	font-size: 14px;
	font-weight: normal;
}

