	border: none;
	margin-bottom: 2px;
}

.card-header {
	background-color: #f8f8f8;
	padding: 6px 10px;
	border: none;
	border-radius: 4px;
}

.card-header:hover {
	background-color: #f6f6f6;
}

#languages a {
	color: #333;
	font-size: 14px;
}

.ui-dialog {
	color: #555;
	font-size: 14px;
	font-weight: normal;
	font-style: normal;
	background-color: rgba(253,253,253,0.6); 
	/*background-color: rgba(0, 0, 0, 0.4); */
	left: 0px;
	top: 0px;
}

#condicoesArmazenamento .card-header {
	background-color: #f1f1f1;
}

#alertas .card-header {
	background-color: #f1f1f1;
}

.jumbotron {
	margin: 0;
	padding: 0;
	min-height: 440px;
	background-color: #F4F8FB;
}

.jumbotron-fluid {
	padding: 0;
